CREATE TABLE IF NOT EXISTS comentarios (id BIGSERIAL PRIMARY KEY,pagina VARCHAR(20) NOT NULL CHECK (pagina IN ('galeria','informacoes','grupo')),nome VARCHAR(80) NOT NULL CHECK (char_length(trim(nome)) BETWEEN 1 AND 80),serie_curso VARCHAR(40) NOT NULL CHECK (char_length(trim(serie_curso)) BETWEEN 1 AND 40),mensagem VARCHAR(1500) NOT NULL CHECK (char_length(trim(mensagem)) BETWEEN 1 AND 1500),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS comentarios_pagina_data_idx ON comentarios (pagina,created_at DESC);
CREATE TABLE IF NOT EXISTS mural_conteudo (pagina VARCHAR(20) PRIMARY KEY CHECK (pagina IN ('galeria','informacoes','grupo')),titulo VARCHAR(120) NOT NULL,descricao VARCHAR(1200) NOT NULL DEFAULT '',imagem_capa TEXT,blocos JSONB NOT NULL DEFAULT '[]'::jsonb,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
